            "current": "  function openTour() {\n    tourReplay = true; // An optional tour returns to the operation that opened it.\n    tourReturnTab = currentTab;\n    tourReplayOpener = document.activeElement;\n    tourStep(0);\n    $('#welcome').classList.remove('hidden');\n  }\n  window.openTour = openTour;\n  const closeTour = async ({ play = false } = {}) => {\n    localStorage.setItem('omerta_tour2', '1');\n    localStorage.setItem('omerta_welcomed', '1');\n    $('#welcome').classList.add('hidden');\n    syncStaticModal($('#welcome'));\n    if (play || !tourReplay) {\n      setTab('streets');\n    } else {\n      const returnTab = tourReturnTab, opener = tourReplayOpener;\n      // The screen render replaces its controls; restore focus only after that render and modal teardown.\n      await setTab(returnTab);\n      if (currentTab !== returnTab || topModal()) return;\n      // The tabpanel survives UX reorderings that can detach a focused child control.\n      const fallback = $(`#tab-${returnTab}`) || $(`#tab-control-${returnTab}`);\n      if (opener?.isConnected && !opener.closest('.hidden, [hidden], [inert]')\n        && opener.getClientRects().length && getComputedStyle(opener).visibility !== 'hidden'\n        && typeof opener.focus === 'function') {\n        opener.focus({ preventScroll: true });\n      } else if (typeof fallback?.focus === 'function') fallback.focus({ preventScroll: true });\n    }\n  };\n  $('#tour-next').onclick = () => (tourAt === TOUR.length - 1\n    ? closeTour({ play: true }) : tourStep(tourAt + 1));\n  $('#tour-back').onclick = () => tourStep(tourAt - 1);\n  $('#tour-skip').onclick = () => closeTour({ play: !tourReplay });\n\n",
