            "current": "  if (workspaceUX) uxModules.push(workspaceUX);\n  for (const factory of [window.createOmertaFeedback, window.createOmertaProgression, window.createOmertaSocial, window.createOmertaNavigation,\n    window.createOmertaTactics, window.createOmertaInvestigation, window.createOmertaCoordination,\n    window.createOmertaFeel, window.createOmertaTools, window.createOmertaIdentity, window.createOmertaStory, window.createOmertaCommunity, window.createOmertaWorld]) {\n    if (!factory) continue;\n    try { const module = factory(uxContext); uxModules.push(module); if (factory === window.createOmertaFeedback) feedbackUX = module; }\n    catch (error) { console.warn('UI enhancement unavailable', error); }\n  }\n  // The shell reveals optional controls without replacing their original action handlers.\n  const gameMenu = $('#game-menu'), cityDirectory = $('#city-directory');\n  const wideNavigation = matchMedia('(min-width: 1001px)');\n  const syncDirectory = () => { cityDirectory.open = wideNavigation.matches; };\n  syncDirectory(); wideNavigation.addEventListener('change', syncDirectory);\n  function closeGameMenu(focus = false) {\n    if (!gameMenu.open) return;\n    gameMenu.open = false;\n    if (focus) gameMenu.querySelector('summary').focus();\n  }\n  function toggleWire(open, focus = false) {\n    const wire = $('#wirepanel');\n    wire.hidden = !open;\n    $('#city-feed-toggle').setAttribute('aria-expanded', String(open));\n    if (open) $('#wire-close').focus();\n    else if (focus) $('#city-feed-toggle').focus();\n  }\n  $('#city-feed-toggle').onclick = () => toggleWire($('#wirepanel').hidden);\n  $('#wire-close').onclick = () => toggleWire(false, true);\n  gameMenu.addEventListener('toggle', () => { if (gameMenu.open) toggleWire(false); });\n  document.addEventListener('click', event => {\n    if (!gameMenu.contains(event.target)) closeGameMenu();\n    if (!wideNavigation.matches && event.target.closest('#city-sidebar [data-tab], #city-sidebar [data-group]')) cityDirectory.open = false;\n  });\n  document.addEventListener('keydown', event => {\n    if (event.key !== 'Escape') return;\n    if (document.querySelector('.modal-bg:not(.hidden), dialog[open]')) return;\n    if (gameMenu.open) { event.preventDefault(); closeGameMenu(true); }\n    else if (!$('#wirepanel').hidden && !document.querySelector('.modal-bg:not(.hidden), dialog[open]')) { event.preventDefault(); toggleWire(false, true); }\n  });\n\n  uxCall('render');\n  applyI18n();\n  mountLangPicker('#game-menu-content'); // console preferences live in the account menu\n  mountLangPicker('#screen-auth .lfoot'); // the landing picker for first-time visitors\n  boot();\n})();\n</script>\n</body>\n</html>\n",
